const inboxMessages =
  $('Search Recent Inbox Messages').all();

const outreachDrafts =
  $('Read Outreach Drafts').all();

const normalize = value =>
  String(value || '').trim().toLowerCase();

const extractEmail = value => {
  const text = String(value || '').trim();

  const angleMatch = text.match(
    /<([^<>\s]+@[^<>\s]+)>/
  );

  if (angleMatch) {
    return normalize(angleMatch[1]);
  }

  const emailMatch = text.match(
    /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i
  );

  return emailMatch
    ? normalize(emailMatch[0])
    : '';
};

const sentDrafts =
  outreachDrafts
    .map(item => item.json)
    .filter(draft =>
      normalize(draft.draft_status) === 'sent'
    );

const sentByRecipient = new Map();
const sentByThread = new Map();

const extractThreadId = draft => {
  const direct = String(draft.gmail_thread_id || '').trim();
  if (direct) return direct;
  const match = String(draft.notes || '').match(
    /Gmail thread ID:\s*([^|\s]+)/i
  );
  return match ? match[1].trim() : '';
};

for (const draft of sentDrafts) {
  const threadId = extractThreadId(draft);
  if (threadId) sentByThread.set(threadId, draft);

  const recipient =
    normalize(draft.recipient_email);

  if (!recipient) {
    continue;
  }

  const existing =
    sentByRecipient.get(recipient);

  if (!existing) {
    sentByRecipient.set(recipient, draft);
    continue;
  }

  const existingDate = new Date(
    existing.sent_at ||
    existing.created_at ||
    0
  ).getTime();

  const draftDate = new Date(
    draft.sent_at ||
    draft.created_at ||
    0
  ).getTime();

  if (draftDate > existingDate) {
    sentByRecipient.set(recipient, draft);
  }
}

const results = [];

for (const messageItem of inboxMessages) {
  const message = messageItem.json;

  const senderEmail =
    extractEmail(message.From || message.from);

  const messageThreadId = String(message.threadId || '').trim();
  const matchedDraft =
    sentByThread.get(messageThreadId) ||
    sentByRecipient.get(senderEmail);

  if (!matchedDraft) {
    continue;
  }

  results.push({
    json: {
      gmail_message_id:
        message.id ||
        message.messageId ||
        '',

      gmail_thread_id:
        message.threadId ||
        '',

      sender:
        message.From ||
        message.from ||
        '',

      sender_email:
        senderEmail,

      recipient:
        message.To ||
        message.to ||
        '',

      subject:
        message.Subject ||
        message.subject ||
        '',

      snippet:
        message.snippet ||
        '',

      internal_date:
        message.internalDate ||
        '',

      labels:
        message.labels ||
        [],

      matched_lead_id:
        matchedDraft.lead_id,

      matched_company:
        matchedDraft.company,

      matched_draft_id:
        matchedDraft.draft_id,

      original_subject:
        matchedDraft.subject,

      original_sent_at:
        matchedDraft.sent_at,

      raw_message:
        message,
    },
  });
}

return results;

const matchedReplies =
  $('Match Replies to Outreach Leads').all();

const crmRows =
  $('Read CRM Master').all();

const normalize = value =>
  String(value || '').trim().toLowerCase();

const latestReplyByLead = new Map();

for (const replyItem of matchedReplies) {
  const reply = replyItem.json;

  const leadId =
    normalize(reply.matched_lead_id);

  if (!leadId) {
    continue;
  }

  const existing =
    latestReplyByLead.get(leadId);

  if (!existing) {
    latestReplyByLead.set(leadId, reply);
    continue;
  }

  const existingDate =
    Number(existing.internal_date || 0);

  const replyDate =
    Number(reply.internal_date || 0);

  if (replyDate > existingDate) {
    latestReplyByLead.set(leadId, reply);
  }
}

const results = [];

for (const [leadId, reply] of latestReplyByLead) {
  const crmItem = crmRows.find(item =>
    normalize(item.json.lead_id) === leadId
  );

  if (!crmItem) {
    continue;
  }

  const crm = crmItem.json;

  const alreadyProcessed =
    normalize(crm.last_reply_message_id) ===
    normalize(reply.gmail_message_id);

  if (alreadyProcessed) {
    continue;
  }

  results.push({
    json: {
      ...reply,

      crm_row_number:
        crm.row_number,

      current_lead_status:
        crm.lead_status || '',

      current_outreach_status:
        crm.outreach_status || '',

      current_follow_up_count:
        Number(crm.follow_up_count || 0),

      previous_reply_message_id:
        crm.last_reply_message_id || '',
    },
  });
}

return results;

const item = $json;
const message = item.raw_message || {};

const decodeBase64Url = value => {
  if (!value) {
    return '';
  }

  try {
    return Buffer
      .from(
        String(value)
          .replace(/-/g, '+')
          .replace(/_/g, '/'),
        'base64'
      )
      .toString('utf8');
  } catch (error) {
    return '';
  }
};

const collectParts = payload => {
  const parts = [];

  const walk = part => {
    if (!part) {
      return;
    }

    const mimeType =
      String(part.mimeType || '').toLowerCase();

    const data =
      part.body?.data || '';

    if (
      data &&
      (
        mimeType === 'text/plain' ||
        mimeType === 'text/html'
      )
    ) {
      parts.push({
        mimeType,
        text: decodeBase64Url(data),
      });
    }

    for (const child of part.parts || []) {
      walk(child);
    }
  };

  walk(payload);

  return parts;
};

const stripHtml = html =>
  String(html || '')
    .replace(
      /<(script|style|noscript)[^>]*>[\s\S]*?<\/\1>/gi,
      ' '
    )
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/\s+\n/g, '\n')
    .replace(/\n\s+/g, '\n')
    .replace(/[ \t]{2,}/g, ' ')
    .trim();

const parts =
  collectParts(message.payload);

const plainPart =
  parts.find(part =>
    part.mimeType === 'text/plain'
  );

const htmlPart =
  parts.find(part =>
    part.mimeType === 'text/html'
  );

let replyText =
  message.text ||
  message.textPlain ||
  plainPart?.text ||
  stripHtml(
    message.textHtml ||
    htmlPart?.text ||
    ''
  ) ||
  item.snippet ||
  '';

replyText = String(replyText)
  .replace(/\r/g, '')
  .split(
    /\n(?:On .+ wrote:|El .+ escribió:|-{2,}\s*Original Message\s*-{2,})/i
  )[0]
  .replace(/\n{3,}/g, '\n\n')
  .trim();

return {
  json: {
    ...item,

    reply_text:
      replyText,

    reply_content_status:
      replyText
        ? 'Content extracted'
        : 'Content unavailable',
  },
};

