const reply =
  $('Extract Reply Content').item.json;

const output = $json.output || [];

let rawText = '';

for (const message of output) {
  for (const content of message.content || []) {
    if (
      content.type === 'output_text' &&
      content.text
    ) {
      rawText = content.text;
      break;
    }
  }

  if (rawText) {
    break;
  }
}

if (!rawText) {
  throw new Error(
    'The model returned no classification.'
  );
}

let classificationResult;

try {
  classificationResult =
    JSON.parse(rawText);
} catch (error) {
  throw new Error(
    'The classification does not contain valid JSON.'
  );
}

const allowedClassifications = [
  'Interested',
  'More information',
  'Not interested',
  'Wrong contact',
  'Out of office',
  'Manual review',
];

const classification =
  allowedClassifications.includes(
    classificationResult.classification
  )
    ? classificationResult.classification
    : 'Manual review';

const today =
  new Date().toISOString().slice(0, 10);

const addDays = days => {
  const date = new Date(`${today}T12:00:00`);
  date.setDate(date.getDate() + days);
  return date.toISOString().slice(0, 10);
};

let leadStatus =
  reply.current_lead_status || 'Qualified';

let outreachStatus =
  'Replied';

let nextActionDate =
  today;

if (classification === 'Interested') {
  leadStatus = 'Qualified';
  outreachStatus = 'Replied';
}

if (classification === 'More information') {
  leadStatus = 'Qualified';
  outreachStatus = 'Replied';
}

if (classification === 'Not interested') {
  leadStatus = 'Disqualified';
  outreachStatus = 'Stopped';
  nextActionDate = '';
}

if (classification === 'Wrong contact') {
  leadStatus = 'Researching';
  outreachStatus = 'Stopped';
}

if (classification === 'Out of office') {
  outreachStatus = 'Sent';

  nextActionDate =
    classificationResult.return_date ||
    addDays(7);
}

const messageDate = reply.internal_date
  ? new Date(
      Number(reply.internal_date)
    ).toISOString().slice(0, 10)
  : today;

return {
  json: {
    lead_id:
      reply.matched_lead_id,

    lead_status:
      leadStatus,

    outreach_status:
      outreachStatus,

    next_action_date:
      nextActionDate,

    last_reply_message_id:
      reply.gmail_message_id,

    last_reply_date:
      messageDate,

    reply_classification:
      classification,

    reply_summary:
      String(
        classificationResult.summary || ''
      ).trim(),

    reply_requires_action:
      Boolean(
        classificationResult.requires_action
      ),

    recommended_action:
      String(
        classificationResult.recommended_action ||
        ''
      ).trim(),

    reply_confidence:
      String(
        classificationResult.confidence ||
        'low'
      ).trim(),

    source_sender:
      reply.sender_email,

    source_subject:
      reply.subject,
  },
};
